def throttle_function(s: str) -> str:
    """Find the longest palindromic substring using expand-around-center (O(n^2) time, O(1) space)."""
    if len(s) < 2:
        return s

    start, end = 0, 0

    def expand(left: int, right: int) -> tuple[int, int]:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        # Odd-length palindromes (single center)
        l1, r1 = expand(i, i)
        if r1 - l1 > end - start:
            start, end = l1, r1

        # Even-length palindromes (double center)
        l2, r2 = expand(i, i + 1)
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start : end + 1]


