    assert throttle_function("") == ""


def test_long_palindrome():
    # 1000-char string with a 51-char palindrome embedded
    s = "a" * 475 + "racecar" + "b" * 518
    assert throttle_function(s) == "a" * 475 + "racecar" + "a" * 0 or throttle_function(s) == "a" * 475
    # The longest run of 'a's (475) beats "racecar" (7)
    assert throttle_function(s) == "a" * 475


def test_spaces_and_special_chars():
    assert throttle_function("a b a") == "a b a"
    assert throttle_function("a!b!a") == "a!b!a"


def test_unicode():
    assert throttle_function("abcba") == "abcba"
    # Greek letters
    assert throttle_function("αβγβα") == "αβγβα"


def test_nested_palindromes():
    # "abacaba" contains several nested palindromes; the full string is one
    assert throttle_function("abacaba") == "abacaba"


