import unittest


class TestThrottleFunction(unittest.TestCase):

    def test_basic_odd(self):
        self.assertIn(throttle_function("babad"), ("bab", "aba"))

    def test_basic_even(self):
        self.assertEqual(throttle_function("cbbd"), "bb")

    def test_single_char(self):
        self.assertEqual(throttle_function("a"), "a")

    def test_two_chars_different(self):
        result = throttle_function("ab")
        self.assertIn(result, ("a", "b"))

    def test_two_chars_same(self):
        self.assertEqual(throttle_function("aa"), "aa")

    def test_entire_string_is_palindrome(self):
        self.assertEqual(throttle_function("racecar"), "racecar")
        self.assertEqual(throttle_function("abba"), "abba")

    def test_all_same_chars(self):
        self.assertEqual(throttle_function("aaaa"), "aaaa")
        self.assertEqual(throttle_function("bbbbbb"), "bbbbbb")

    def test_no_palindrome_longer_than_one(self):
        result = throttle_function("abcdefg")
        self.assertEqual(len(result), 1)
        self.assertIn(result, "abcdefg")

    def test_palindrome_at_start(self):
        self.assertEqual(throttle_function("abacdfgdcaba"), "aba")

    def test_palindrome_at_end(self):
        self.assertEqual(throttle_function("xyzaba"), "aba")

    def test_even_length_palindrome(self):
        self.assertEqual(throttle_function("cabbad"), "abba")
        self.assertEqual(throttle_function("abbac"), "abba")

    def test_odd_length_palindrome(self):
        self.assertEqual(throttle_function("abcba"), "abcba")

    def test_empty_string(self):
        self.assertEqual(throttle_function(""), "")

    def test_long_run_of_same_char(self):
        s = "a" * 475 + "racecar" + "b" * 518
        self.assertEqual(throttle_function(s), "a" * 475)

    def test_spaces_in_palindrome(self):
        self.assertEqual(throttle_function("a b a"), "a b a")

    def test_special_chars(self):
        self.assertEqual(throttle_function("a!b!a"), "a!b!a")

    def test_unicode(self):
        self.assertEqual(throttle_function("αβγβα"), "αβγβα")

    def test_nested_palindromes(self):
        self.assertEqual(throttle_function("abacaba"), "abacaba")

    def test_long_string_performance(self):
        """10 000 chars should finish quickly — no exponential blowup."""
        s = "a" * 10_000
        self.assertEqual(throttle_function(s), s)


